-- 木槌: 绕**支点**做刚体旋转 (支点落在柄的中后部, 不是柄的端点) ---------------
--   linit 2026-11-23: "以手柄接近尾部为支点, 旋转向下敲击, 然后慢一点抬升"。
--   原实现是整张位图**垂直平移** —— 槌身倾角全程不变, 只是一块图上下滑,
--   所以看着"直上直下、别扭、像撕裂"。位图无法旋转, 改成几何绘制(柄+球头),
--   角度就能逐帧连续变化 —— 这才是"挥"。
--   支点 x=280 (比原柄尾 300 内缩 20px), 再由 MAL_TAIL 把柄尾延伸回 300,
--   于是"握点"在柄身上、尾巴露在外面; 球头(敲击点)位置全程不变。
--   ★ linit 2026-11-23 (第 3 轮): "敲击挥下的速度太慢" ⇒ 落槌段 100→60ms;
--     "支点怎么还是在手柄尾部" ⇒ 支点**不再是柄的端点**: 柄在支点之后再延伸
--     MAL_TAIL 像素露出尾部, 视觉上支点落在柄的中后部 (像真握着柄)。
local MAL_T1, MAL_T2, MAL_T3, MAL_ANIM = 60, 90, 500, 510
local MAL_PX, MAL_PY = 280, 114        -- 支点(绝对坐标): 手"握"在这里
                                       --   linit 2026-11-23: "支点太靠后, 往前移 20px"
                                       --   ⇒ 300→280。杆长同步减 20, 球头(敲击点)
                                       --   位置**不变**, 只是握点前移、柄露出更短。
local MAL_L  = 89                      -- 支点 → 球头中心 的距离 (原 108.6 - 20)
local MAL_TAIL = 20                    -- 支点 → 柄尾 的距离 (柄尾露在支点外面, 不是端点是支点)
                                       --   20 ⇒ 柄尾回到 x≈300, 与最初图纸一致, 球头位置不变。
local MAL_R  = 18                      -- 球头半径 (原图列宽峰值 37)
local MAL_A0, MAL_A1 = 195, 170        -- 静止角 / 击打角 (度, y 轴向下)
                                       --   195°: 球头中心 (194,91) 底 y109 (离木鱼顶 36px)
                                       --   170°: 球头中心 (192,129) 底 y147 (压进木鱼 2px)
local MAL_W0, MAL_W1 = 11, 9           -- 柄宽: 靠球头 / 靠尾 (原图等宽 10, 做一点锥形)

-- 木槌在时刻 age 的倾角 (度)。曲线: 加速落下 → 压住 → smoothstep 缓抬
local function mal_ang(age)
  if age <= 0 or age >= MAL_T3 then return MAL_A0 end
  local d = MAL_A0 - MAL_A1
  if age < MAL_T1 then
    local t = age / MAL_T1
    return MAL_A0 - d * t * t                                 -- 越落越快(像自重)
  elseif age < MAL_T2 then
    return MAL_A1                                             -- 压住
  end
  local s = (age - MAL_T2) / (MAL_T3 - MAL_T2)
  return MAL_A1 + d * s * s * (3 - 2 * s)                     -- smoothstep: 起步慢收尾更慢
end

