-- 工具 -----------------------------------------------------------------------
local function hex2bin(h)
  local t = {}
  for i = 1, #h, 2 do
    t[#t + 1] = string.char(tonumber(h:sub(i, i + 1), 16))
  end
  return table.concat(t)
end

-- 十进制字符串整除 (保 epoch 精度: 本项目 Lua number 32bit float,
-- 1.7e9 只有 ~128 秒精度, 直接 tonumber 会算错"哪一天")
local function dec_div(s, d)
  local q, r = {}, 0
  for i = 1, #s do
    local c = s:byte(i) - 48
    if c < 0 or c > 9 then return nil end
    r = r * 10 + c
    local qi = math.floor(r / d)
    q[#q + 1] = string.char(48 + qi)
    r = r - qi * d
  end
  local out = table.concat(q):gsub("^0+", "")
  if out == "" then out = "0" end
  return out
end

-- 2020-01-01T00:00:00Z; 早于它视为刷机/未校时
local EPOCH_MIN = "1577836800"

-- 取一次可信的 epoch 字符串 (不可信/桥缺失 → nil)。day_key 与 day_index 共用。
local function epoch_str()
  local u = app.util
  if type(u) ~= "table" then return nil end
  local fn = u.epoch
  if fn == nil then return nil end
  local ok, e = pcall(fn)
  if not ok or type(e) ~= "string" or #e < 10 then return nil end
  if #e == 10 and e < EPOCH_MIN then return nil end
  return e
end

local function day_key_now()
  local e = epoch_str()
  if not e then return nil end

  -- 用 localtime 的月/日做 key (svc_time 固定 TZ=UTC-8, 即北京时间日界)
  local sd = app.sys and app.sys.date
  if sd then
    local ok2, m, d = pcall(sd)
    if ok2 and type(m) == "number" and type(d) == "number"
       and m >= 1 and m <= 12 and d >= 1 and d <= 31 then
      local yr = tonumber(dec_div(e, 31536000)) or 0
      return yr .. "-" .. m .. "-" .. d
    end
  end
  return dec_div(e, 86400)
end

-- 十进制字符串 + n (n < 100000): 用于把 epoch 加上时区偏移再做整除
local function dec_add(s, n)
  local carry, out = n, {}
  for i = #s, 1, -1 do
    local d = (s:byte(i) - 48) + carry % 10
    carry = math.floor(carry / 10) + math.floor(d / 10)
    out[#out + 1] = string.char(48 + d % 10)
  end
  while carry > 0 do
    out[#out + 1] = string.char(48 + carry % 10)
    carry = math.floor(carry / 10)
  end
  return string.reverse(table.concat(out))
end

-- 本地日序号 (北京时间): 连续天数只能靠"相差 1"判断, 所以不能拿 "年-月-日"
-- 字符串比 (跨月跨年就断了)。epoch+8h 后按 86400 取整 ⇒ 5 位整数,
-- 32 位 float 可精确表示 (2^24 以内), 转 number 安全。
local function day_index_now()
  local e = epoch_str()
  if not e then return nil end
  local n = tonumber(dec_div(dec_add(e, 28800), 86400))
  if not n then return nil end
  return math.floor(n)
end

-- 数字显示: 超过 6 位改用"万/亿", 否则右上角会被挤爆
local function fmt_num(n)
  if n >= 100000000 then
    return tostring(math.floor(n / 100000000)) .. "亿"
  elseif n >= 1000000 then
    local w = math.floor(n / 10000)
    if w >= 10000 then return tostring(math.floor(w / 10000)) .. "亿" end
    return tostring(w) .. "万"
  end
  return tostring(n)
end

local function refresh_strings()
  G.s_total = fmt_num(G.total)
  G.s_today = G.today_ok and fmt_num(G.today) or "--"
  G.s_sess  = fmt_num(G.session)
  G.s_mile  = "里程碑 " .. G.mile .. "/4"
  if G.mile < #MILE then
    G.s_next = MILE[G.mile + 1][1] .. " " .. MILE[G.mile + 1][2]
  else
    G.s_next = "已达成"
  end
  G.s_pop_w = app.mixw(G.s_pop)
end

-- 存档 -----------------------------------------------------------------------
local function load_state()
  G.total = app.nvs.get_int(K_TOTAL) or 0
  G.mile  = app.nvs.get_int(K_MS) or 0
  G.streak   = app.nvs.get_int(K_STREAK) or 0
  G.last_day = app.nvs.get_int(K_LASTD) or 0
  local o = app.nvs.get_int(K_OPT)
  if o ~= nil then
    G.snd = (o % 2) == 1
    G.vib = o >= 2
  end

  local dk = app.nvs.get_str(K_DAY)
  local td = app.nvs.get_int(K_TODAY)
  G.day_key  = day_key_now()
  G.today_ok = (G.day_key ~= nil)
  if G.today_ok then
    if dk == G.day_key and td ~= nil then
      G.today = td
    else
      G.today = 0
      G.dirty = true
    end
    -- 断签: 上次圆满既不是今天也不是昨天 ⇒ 连日归零。
    --   不等"下次圆满才纠正": 否则离开一星期回来, 统计里还显示着"连续 12 天" —— 假的。
    local di = day_index_now()
    if di and G.last_day > 0 and G.last_day < di - 1 then
      G.streak = 0
      G.dirty = true
    end
  else
    G.today = 0
  end

  -- 常驻祝福语用哪一句: 按**日序号**取模 ⇒ 同一天恒定同一句, 第二天自动换。
  --   与"是否圆满"解耦 —— 圆满与否由 halo_level() 判, 这里只决定文案。
  local dbi = day_index_now()
  G.bless_i = dbi and (dbi % #BLESS + 1) or 1
end

-- 延迟批量保存: 30 秒节流 + 退出/后台强刷。
-- ★ 每次 save 会写多个 NVS key, 每个 key 各一次 flash commit(关 cache);
--   Lua 侧已确认可以写(音效就是应用自己写出来的), 但频率越低越好。
local function save_state(force)
  if not G.dirty then return end
  local now = G.now
  if not force and (now - G.last_save) < 30000 then return end
  G.last_save = now
  local opt = (G.snd and 1 or 0) + (G.vib and 2 or 0)
  local ok = pcall(function()
    if G.total ~= G.w_total then app.nvs.set_int(K_TOTAL, G.total); G.w_total = G.total end
    if G.mile  ~= G.w_mile  then app.nvs.set_int(K_MS, G.mile);     G.w_mile  = G.mile  end
    if opt     ~= G.w_opt   then app.nvs.set_int(K_OPT, opt);       G.w_opt   = opt     end
    if G.streak   ~= G.w_streak then app.nvs.set_int(K_STREAK, G.streak);   G.w_streak = G.streak end
    if G.last_day ~= G.w_lastd  then app.nvs.set_int(K_LASTD, G.last_day);  G.w_lastd  = G.last_day end
    if G.today_ok and G.day_key then
      if G.day_key ~= G.w_day then app.nvs.set_str(K_DAY, G.day_key); G.w_day = G.day_key end
      if G.today   ~= G.w_today then app.nvs.set_int(K_TODAY, G.today); G.w_today = G.today end
    end
  end)
  G.dirty = not ok
end

-- 音效 -----------------------------------------------------------------------
-- ★ 音效字节数从 hex 串长度直接算 (#SFX_HEX / 2) —— 不用解码就能判断"文件是否已就位"。
--   原来无条件先 hex2bin 再比大小, 12 KB 音效要跑 1.2 万次 string.char + concat,
--   每次进应用白花几十 ms。现在只有**首次落盘**那一次才真的解码。
local SFX_LEN = #SFX_HEX / 2

-- 兼容: 老固件没有预载 API ⇒ 退回"每次敲击读文件"的旧路径 (音质完全一样,
--       只是敲击时会卡一下, 因为 52KB 要从 SPI flash 读)。新固件自动走预载。
local SFX_BUF = (app.rec and app.rec.preload and app.rec.play_buf) ~= nil

local function sfx_kick()      -- 起一声: 预载缓存优先, 没有就走文件
  if SFX_BUF then return app.rec.play_buf() end
  return app.rec.play(G.sfx_path)
end

-- ★★ 音效**预载进 PSRAM** (2026-11-23 linit: "音效提前加载到缓存psram, 该用就用,
--    退出了会卸载")。进应用时读一次文件 → app.rec.preload() 拷进播放器的 PSRAM 缓存,
--    之后每次敲击走 app.rec.play_buf() ⇒ **零文件 IO**。
--    为什么这是必须的 (实测数据):
--      · /store 在 SPI flash, 读它要关 cache; PSRAM 与 flash 共用 cache ⇒ 关闭期间
--        PSRAM 不可访问。52KB 走 SPIFFS 只有 ~285KB/s = 188ms, 期间 UI 一帧都不出
--        ⇒ 敲击动画"卡一下然后突然跳过去"。
--      · wavply 任务优先级(7) 高于 UI 主任务, 那 188ms 里主线程完全拿不到 CPU。
--      · 更早的 rst=4 PANIC (点木鱼就重启) 也是这条路径: 关 cache 时若栈在 PSRAM 直接崩。
--    预载后播放只做 memcpy, 三个问题一起消失。
local function ensure_sfx()
  for _, p in ipairs(SFX_PATHS) do
    if app.fs.size(p) == SFX_LEN then
      if not SFX_BUF then                       -- 老固件: 只能播文件
        G.sfx_ok, G.sfx_path = true, p
        return
      end
      local bin = app.fs.read(p)
      if bin and #bin == SFX_LEN and app.rec.preload(bin) == 0 then
        G.sfx_ok, G.sfx_path = true, p
        return
      end
    end
  end
  -- 文件不存在/不完整: 从内嵌 hex 解一次, 落盘后照样预载
  local bin = hex2bin(SFX_HEX)
  for _, p in ipairs(SFX_PATHS) do
    local ok = pcall(function() return app.fs.write(p, bin) end)
    if ok and app.fs.size(p) == SFX_LEN then
      G.sfx_ok, G.sfx_path = true, p
      for _, old in ipairs(SFX_OLD) do pcall(function() app.fs.remove(old) end) end
      if not SFX_BUF then return end          -- 老固件: 文件写好了就能播
      if app.rec.preload(bin) == 0 then return end
      break
    end
    pcall(function() app.fs.remove(p) end)
  end
  app.log("[muyu] sfx preload failed, running muted")
end

-- 一次按下 = 一次完整音效 (linit 2026-11-23 定):
--   · **不排队**: 上一声还在响就再敲 → 直接打断重来。排队"补播"会凭空多出
--     一声不属于任何一次按压的声音, 而且越敲越密, 听起来就是"加快播放"。
--   · **不改速率**: 播放速率只由 WAV 文件头决定, 应用层从不碰。
--   · 只有 wavply 任务还没退干净(单通道, 一次只有一个)时, 才在**下一帧**重试一次, 150ms 放弃。
local function sfx_start()
  if not (G.snd and G.sfx_ok) then return end
  -- 无条件 stop: 有在播的 → 置停止并**清空 PCM 环形缓冲**(C 侧 audio_player_stop_all
  -- 已补 flush, 否则旧尾音会继续从缓冲里播完, 听着就是"没打断"); 没在播 → 空操作。
  app.rec.stop_play()
  G.sfx_try = (sfx_kick() ~= 0) and G.now or nil
end

local function sfx_tick()
  if not G.sfx_try then return end
  if (G.now - G.sfx_try) > 150 then           -- 等太久就丢掉, 绝不积压
    G.sfx_try = nil
    return
  end
  if app.rec.playing() then return end        -- 旧任务还没退, 下一帧再看
  G.sfx_try = nil
  if G.snd and G.sfx_ok and sfx_kick() ~= 0 then G.sfx_try = G.now end
end

-- 敲击 -----------------------------------------------------------------------
-- 弹窗期间/刚关掉的一小段时间**一律不认敲击**。
--   ⚠ 这是应用侧的第二道闸, 而且必须自己有一道:
--     弹窗是页面栈里的 modal 页, os_core 每帧只 poll **栈顶**页 (os_core.c:672),
--     所以弹窗打开期间本应用的 poll() 一次都不跑 ⇒ 桥里那套"弹窗期间 + 关闭后
--     120ms 屏蔽"旧实现是靠脚本调用时观察 os_dialog_depth() 来布防的, 观察不到就
--     从不布防, 对 Lua 应用等于不存在。2026-11-23 linit 报「点设置里的项, 会透过
--     弹窗敲一下木鱼」即此。(框架侧同日已改成由 os_dialog_pop 权威记录关窗时刻;
--     应用侧这道闸不依赖固件版本, 老固件上同样有效。)
local DLG_QUIET_MS = 120
-- 弹窗状态自愈: 页面**只有在弹窗关掉后**才会被 poll, 所以"G.pop 有值却还在 poll"
--   持续超过这个时长 ⇒ 那个弹窗一定是被别处关掉的(框架 clear_all/异常复位),
--   结果永远不会来。不清理就会把 G.pop 永久挂住 ⇒ 应用再也敲不动。
--   清理是安全的: 弹窗真开着的时候页面根本不会 poll, 不会误清。
local POP_STALE_MS = 5000
local function dlg_busy()
  if G.pop ~= nil then
    if (G.now - (G.pop_open_t or 0)) < POP_STALE_MS then return true end
    G.pop = nil                    -- 超时: 认定为残留, 放行
  end
  return G.dlg_close ~= nil and (G.now - G.dlg_close) < DLG_QUIET_MS
end

-- "今日圆满": 跨过目标那一下记一次连日 + 抽一句祝福语 (每天只触发一次)
local function mark_goal()
  if not G.today_ok then return end
  local di = day_index_now()
  if not di or G.last_day == di then return end   -- 今天已经记过
  G.streak = (G.last_day == di - 1) and (G.streak + 1) or 1
  G.last_day = di
  G.bless_i = di % #BLESS + 1                     -- 文案按日序号固定; 条幅从此刻起常驻到当天结束
  G.dirty = true                                   -- 交给 30s 节流 / 退出强刷落盘
  app.redraw()                                     -- 让佛光当帧就亮起来
end

local function do_hit()
  G.now = app.millis() or G.now
  if dlg_busy() then return end                  -- 弹窗开着/刚关: 这一下是给弹窗的, 不算敲木鱼
  if (G.now - G.last_tap) < 60 then return end   -- 60ms 去抖: 抖动能滤掉, 快速连点(≈150ms/次)照收
  G.last_tap = G.now

  G.total   = G.total + 1
  G.session = G.session + 1
  if G.today_ok then G.today = G.today + 1 end
  G.hit_t = G.now
  G.dirty = true

  -- 追加一条独立飘字 (不影响已在飘的那些)。
  --   ★ 横向用 **5 个槽位轮流 + 小抖动**, 不用纯随机: 纯随机时两张前后脚的
  --     飘字会抽到相近的 dx, 在屏幕上叠成一团 (1bpp 没有半透明, 叠起来就是糊)。
  --     槽位 -2..2 ⇒ 间距 25px, 加 ±10 抖动, 总幅 ±60; 连点几下必然左右分开。
  G.seed = (G.seed * 75 + 74) % 65537
  local ps = G.pops
  if #ps >= POP_MAX then table.remove(ps, 1) end
  local slot = (#ps % 5) - 2
  ps[#ps + 1] = { t = G.now, dx = slot * 25 + (G.seed % 21) - 10 }

  if G.vib then app.vibrate(30) end          -- 后一次覆盖前一次, 不积压
  sfx_start()

  local idx = 0
  for i = 1, #MILE do
    if G.total >= MILE[i][1] then idx = i end
  end
  if idx > G.mile then
    G.mile = idx
    app.dlg.toast(MILE[idx][2], 2000)            -- 里程碑: 系统 toast, 不自绘
  end

  if G.today_ok and G.today == GOAL then mark_goal() end

  refresh_strings()
  app.redraw()                                -- 立刻显示"敲下"帧
end

-- 基础图元 -------------------------------------------------------------------
local PI = 3.14159265

-- 木槌: 柄(按列扫描填充的梯形) + 球头(实心圆), 全部按角度现场算 -
--   支点是**旋转中心**, 不是柄的端点: 柄从球头一路画到"支点 + MAL_TAIL 的尾巴",
--   所以支点落在柄的中后部, 视觉上像手握住柄而不是捏住柄尖。
--   ★ 全程**刚体旋转**: 柄长恒为 MAL_L+MAL_TAIL, 宽度只按列线性锥化, 不做任何
--     拉伸/缩放 —— 挥动的观感只来自"角度 + 球头沿圆弧的位置"同时变化。
--   ★★ 2026-11-23 linit 报「挥动时柄上有白条撕裂、尾部硬切割」:
--     ① 白条: 原来每列高度按 w*0.5 取半像素再 floor, 相邻列算出的上下界会错开
--        1px ⇒ 柄身上出现**横穿的白缝**, 而且角度一变缝就换位置, 看着像撕裂。
--        现在每列高度取整 (wi), 上界 = 中心 - wi/2, 高度恒为 wi ⇒ 相邻列必然重叠。
--     ② 硬切割: 原来柄尾就是一个竖直的平口。现在补一个半径 = 尾宽的实心圆头,
--        圆心沿柄方向内缩 r-1, 外缘正好接住柄尾端点, 长度不变。
--   ★ 柄接近水平(倾角 8°~12°), 所以**按列**填充(vline); 按行会因 x 跨度大留缝。
local function draw_mallet(a)
  local rad = a * PI / 180
  local ca, sa = math.cos(rad), math.sin(rad)
  local cx = MAL_PX + MAL_L * ca                 -- 球头中心
  local cy = MAL_PY + MAL_L * sa
  -- 柄尾: 从支点沿**反方向**再延伸 MAL_TAIL ⇒ 支点在柄身上, 尾巴露在外面
  local tx = MAL_PX - MAL_TAIL * ca
  local ty = MAL_PY - MAL_TAIL * sa
  local n = math.floor(tx - cx)                  -- 柄的列数 (球头 → 柄尾, ~109)
  if n > 0 then
    -- ★ 按**整数列**遍历 (不是 x += ddx 累积): 累积步长 1.007 时, 某一列的
    --   floor(x+0.5) 会一次跳 2 ⇒ 中间那列根本没画 = 柄上一道竖白缝, 而且角度
    --   一变缝就换位置 (linit 报的"挥动时白条撕裂"就是这个)。逐列反算 y 没有
    --   累积误差, 列号严格 +1。
    local x0 = math.floor(cx + 0.5)
    local x1 = math.floor(tx + 0.5)
    local span = tx - cx
    local k_dy = (ty - cy) / span                -- 每列 y 增量
    local k_dw = (MAL_W1 - MAL_W0) / span        -- 每列宽度增量
    for xi = x0, x1 do
      local dxr = xi - cx
      local wi = math.floor(MAL_W0 + dxr * k_dw + 0.5)   -- 本列**整数**线宽(高度)
      local y0 = math.floor(cy + dxr * k_dy - wi * 0.5 + 0.5)
      app.vline(xi, y0, y0 + wi - 1, BK)                 -- 高度恒为 wi ⇒ 相邻列必重叠
    end
  end
  -- 柄尾圆头 (不是竖切): 半径比尾宽大 1px, 圆心沿柄内缩 r-1 ⇒ 外缘刚好到 tx
  local r = math.floor(MAL_W1 * 0.5 + 0.5) + 1
  local ex = tx - (r - 1) * ca
  local ey = ty - (r - 1) * sa
  local rix, riy = math.floor(ex + 0.5), math.floor(ey + 0.5)
  for dy = -r, r do
    local d2 = r * r - dy * dy
    if d2 >= 0 then
      local dx = math.floor(math.sqrt(d2) + 0.5)
      app.hline(rix - dx, rix + dx, riy + dy, BK)
    end
  end
  local icx, icy = math.floor(cx + 0.5), math.floor(cy + 0.5)
  for dy = -MAL_R, MAL_R do
    local d = MAL_R * MAL_R - dy * dy
    if d >= 0 then
      local dx = math.floor(math.sqrt(d) + 0.5)
      app.hline(icx - dx, icx + dx, icy + dy, BK)
    end
  end
end

local function disc(cx, cy, r, col)
  for dy = -r, r do
    local d = r * r - dy * dy
    if d >= 0 then
      local dx = math.floor(math.sqrt(d) + 0.5)
      app.hline(cx - dx, cx + dx, cy + dy, col)
    end
  end
end

-- 齿轮: 8 个齿 + 实心盘 + 白色轴孔 (1bpp 小尺寸下这种画法最不容易糊)
local function draw_gear(cx, cy)
  local TEETH = {
    { 0, -11 }, { 8, -8 }, { 11, 0 }, { 8, 8 },
    { 0, 11 }, { -8, 8 }, { -11, 0 }, { -8, -8 },
  }
  for i = 1, #TEETH do
    local tx, ty = cx + TEETH[i][1], cy + TEETH[i][2]
    app.fill(tx - 2, ty - 2, tx + 2, ty + 2, BK)
  end
  disc(cx, cy, GEAR_R, BK)
  disc(cx, cy, 4, WH)
end

-- 数字右对齐 (app.big 每个字符 8*scale 宽)
local function num_r(xr, y, s, sc)
  app.big(xr - #s * 8 * sc, y, s, sc)
end

-- 直线 (Bresenham)。桥里没有 app.line, 佛光的放射线只能自己逐点画:
--   单条 12~20px ⇒ 20 次 app.px; 30 条 ≈ 600 次, 而且只在"呼吸换档"那一帧才重绘。
local function seg(x0, y0, x1, y1)
  local dx, dy = x1 - x0, y1 - y0
  local ax = (dx < 0) and -dx or dx
  local ay = (dy < 0) and -dy or dy
  local sx = (dx < 0) and -1 or 1
  local sy = (dy < 0) and -1 or 1
  local err = ax - ay
  while true do
    app.px(x0, y0, BK)
    if x0 == x1 and y0 == y1 then break end
    local e2 = err * 2
    if e2 > -ay then err = err - ay; x0 = x0 + sx end
    if e2 <  ax then err = err + ax; y0 = y0 + sy end
  end
end

-- 佛光等级: 0=今日未圆满(不画) / 1=圆满 / 2=连续≥3天 / 3=连续≥7天
local function halo_level()
  if not (G.today_ok and G.today >= GOAL) then return 0 end
  if G.streak >= 7 then return 3 end
  if G.streak >= 3 then return 2 end
  return 1
end

-- 佛光: 放射短线, 长短交错(br=呼吸量, pulse=敲击时外扩一下)
--   角度从 168° 到 372° (跨越正上方 270°) ⇒ **底部完全没有线**
local function draw_halo(level, br, pulse)
  local n    = 15 + 6 * level                    -- 21 / 27 / 33 条 (放大后加密, 不显稀疏)
  local r0   = HALO_R0 - level                   -- 层数越高, 内端越贴近本体
  local r1   = HALO_R1 + level * 2 + br + pulse
  local a0   = 270 - HALO_SPAN * 0.5
  local step = HALO_SPAN / (n - 1)
  for i = 0, n - 1 do
    local a = (a0 + i * step) * PI / 180
    local ca, sa = math.cos(a), math.sin(a)
    local r = r1 + (((i % 2) == 0) and 4 or 0)   -- 长短交错, 比等长更像光
    seg(HALO_CX + math.floor(r0 * ca), HALO_CY + math.floor(r0 * sa),
        HALO_CX + math.floor(r   * ca), HALO_CY + math.floor(r   * sa))
  end
end

-- 祝福语条幅: ★ 2026-11-23 linit「池子出来了就固定显示到当天」
--   ⇒ 从"圆满后只闪 3 秒"改成**当天圆满就常驻**: 退出重进、重启都还在, 过了 0 点自然消失。
--   文案按**日序号**取模, 同一天恒定同一句 (每次重绘不会换句子)。
--   位置 y=264: 木鱼底 242 之下、左右"今日/本次"数字之间 —— 既不压木鱼,
--   也不占飘字走廊(200±60, 从 y=100 往上飘)。
local BANNER_Y = 264
local function draw_banner()
  if halo_level() <= 0 then return end        -- 今日没圆满: 完全不画
  local s = BLESS[G.bless_i or 1]
  if not s then return end
  local w = app.mixw(s)
  local x = 200 - math.floor(w / 2)
  -- 白底: 条幅横跨飘字走廊(200±60), 不铺白就会和"功德 +1"叠成一团 (1bpp 无半透明)
  app.fill(x - 4, BANNER_Y - 2, x + w + 3, BANNER_Y + 17, WH)
  app.mix(x, BANNER_Y, s)
  app.hline(x, x + w - 1, BANNER_Y + 18, BK)     -- 下面一条细线, 像条幅下沿
end

-- 主界面 ---------------------------------------------------------------------
local function draw_muyu()
  local age = G.now - G.hit_t
  -- ★ 佛光先画: 木鱼位图是实心黑, 画在后会把内侧的射线压掉 ⇒ 像是从背后透出来
  local lit = halo_level()
  if lit > 0 then
    -- 敲击后 160ms 内光外扩 4px —— 给"这一下"一个呼应, 不做全屏闪光
    local pulse = ((G.now - G.hit_t) < 160) and 4 or 0
    draw_halo(lit, HALO_BREATH[G.halo_ph] or 0, pulse)
  end
  if G.body then
    app.bmpr(MUYU_X + BODY_DX, MUYU_Y + BODY_DY, BODY_W, BODY_H, G.body)
  end
  draw_mallet(mal_ang(age))
end

-- 把**所有**在飘的"功德 +1"画出来 (不是只画最新一条)
local function draw_pop()
  local ps, hw = G.pops, math.floor(G.s_pop_w / 2)
  for i = 1, #ps do
    local p = ps[i]
    local age = G.now - p.t
    if age >= 0 and age <= POP_MS then
      local py = POP_Y0 - math.floor(age * POP_DY / POP_MS)
      -- py 已完全出屏顶 (字高 16) 就不再调 mix: draw_pixel 会裁剪, 但省下 300+ 次越界调用
      if py > -18 then
        app.mix(200 + p.dx - hw, py, G.s_pop)   -- 透明黑字, 不再套黑底块
      end
    end
  end
end

local function draw_main()
  -- 右上: 累计功德 (主体数字)
  app.mix(390 - app.mixw("累计"), 8, "累计")
  num_r(390, 26, G.s_total, 2)

  -- 左下: 今日功德
  app.mix(10, 240, "今日")
  app.big(10, 258, G.s_today, 2)

  -- 右下: 本次
  app.mix(390 - app.mixw("本次"), 240, "本次")
  num_r(390, 258, G.s_sess, 2)

  draw_gear(GEAR_CX, GEAR_CY)
  draw_muyu()
  draw_pop()
  draw_banner()                      -- 祝福语压在最上层
end

-- 设置 / 统计: 标准二级弹窗 (不做全屏页) ----------------------------------------
-- 规范 §5.1: 弹窗一律走 os_dialog, 应用只传文字。设置只有 4 个单意图项,
-- 用 app.dlg.list 就够 —— 全屏页要多画标题/分隔线/返回按钮, 还多一层"返回"栈。
-- ⚠ app.dlg.list 返回 **0 基下标** (dlg_finish_top 传的是 d->sel), -1 = 返回/取消。
local function open_stat()
  G.pop, G.pop_open_t = "stat", G.now
  -- 目标/进度**不显示**: 圆满是彩蛋, 提前剧透就没意思了 (linit 2026-11-23)
  local it = {
    "累计功德：" .. G.s_total,
    "今日功德：" .. G.s_today,
    "本次：" .. G.s_sess,
    "里程碑：" .. G.mile .. "/4",
  }
  if G.streak > 0 then it[#it + 1] = "连续圆满：" .. G.streak .. " 天" end
  app.dlg.list("统计", it, 0, G.today_ok and G.s_next or "日期未校准")
end

-- 开关状态直接写进项文字: list 弹窗不支持控件, 点一下切换再重开刷新文字
local function open_set()
  G.pop, G.pop_open_t = "set", G.now
  app.dlg.list("设置", {
    "声音：" .. (G.snd and "开" or "关"),
    "震动：" .. (G.vib and "开" or "关"),
    "每日统计",
    "清空记录",
  }, 0)
end

-- 弹窗 -----------------------------------------------------------------------
-- ⛔ 一律不自绘确认框/提示框 (2026-11-23 回归规范, docs/规范/界面交互规范.md §2/§5):
--   · 退出确认: 主界面 BACK **不消费**, 由框架 lua_request_exit 弹系统「退出程序?」
--     (page_lua.c:1197) —— 应用侧一行代码都不用写。
--   · 其他确认: app.dlg.confirm(msg), 结果在 poll 里用 app.dlg.result() 取
--     (nil=未选 / -1=取消 / 0=确定), 读完自动清零。
--   · 一次性提示: app.dlg.toast(msg)。
--   自绘的框和系统弹窗长得不一样, 而且 1bpp 没有半透明遮罩 —— 白框盖不住背后的
--   黑色木鱼, 边缘会露黑块, 只能整屏铺白, 代价是背景全丢。

-- 输入 -----------------------------------------------------------------------
local function clear_records()
  G.total, G.today, G.session, G.mile = 0, 0, 0, 0
  G.streak, G.last_day = 0, 0                     -- 连日也一起清 (佛光随之熄灭)
  G.bless_i = nil                                 -- 条幅由 halo_level() 判, 今日未圆满即不画
  -- 强制下次 save 全写
  G.w_total, G.w_today, G.w_mile = -1, -1, -1
  G.w_streak, G.w_lastd = -1, -1
  G.dirty = true
  refresh_strings()
  save_state(true)
  app.dlg.toast("已清空")
  app.redraw()
end

local function toggle(id)
  if id == "snd" then
    G.snd = not G.snd
    if not G.snd then
      G.sfx_try = nil                              -- 关声音: 丢掉重试, 并立刻掐掉正在响的
      if app.rec.playing() then app.rec.stop_play() end
    end
  elseif id == "vib" then
    G.vib = not G.vib
    if G.vib then app.vibrate(30) end            -- 打开时给一次触感确认
  end
  G.dirty = true
end

local function on_tap(x, y)
  -- ⚠ 别信"弹窗开着时页面层拿不到触摸" —— 弹窗是 modal 页, 页面层**确实**不 poll,
  --   但弹窗关掉那一帧 poll 立刻恢复, 手指还按在屏幕上, 坐标正好落在木鱼热区里。
  --   所以真正的闸门是 dlg_busy()/need_release, 见 do_hit 与 poll。
  local dx, dy = x - GEAR_CX, y - GEAR_CY
  if dx * dx + dy * dy <= GEAR_HIT * GEAR_HIT then
    open_set()                       -- 齿轮 → 标准二级弹窗
    return
  end
  if x >= HIT_X0 and x <= HIT_X1 and y >= HIT_Y0 and y <= HIT_Y1 then
    do_hit()
  end
end

-- 全局回调 (必须全局: 桥按名字取值) ------------------------------------------
function render()
  app.clear(WH)
  draw_main()                        -- 只有主界面一个全屏页, 设置/统计都是系统弹窗
end

function poll()
  G.now = app.millis() or G.now

  local x, y = app.touch()
  if x then
    -- ★ 只在"真正的按下边沿"触发, 并且抬起后 40 ms 内不认新手势。
    --   触摸芯片报点是会抖的(一帧有/一帧没有), 原来只判 t_down 会被抖成连发:
    --   按一下连着敲 3~4 下、音效"哒哒哒哒" —— 2026-11-23 linit 报障。
    --   宽限原来给 70ms, 但"快速连点"每次按压周期只有 ~150ms、抬起到下次按下
    --   可能不足 70ms ⇒ 第 2 下被静默吞掉, 听着像"没重新放"。40ms 够挡住抖动
    --   (抖点在相邻 1~2 帧内, ≈16~33ms), 又不妨碍连点。
    -- ★★ need_release: 弹窗关掉时手指通常还按在屏上(就是点弹窗那一下)。
    --   这一下**绝不能**算敲木鱼, 所以关窗后必须先看到一个"抬起", 才允许下一次按压。
    if not G.need_release and not G.t_down and (G.now - G.up_t) >= 40 then
      G.t_down = true
      on_tap(x, y)
    end
  else
    G.need_release = false             -- 见到抬起 ⇒ 解锁下一次按压
    if G.t_down then
      G.t_down = false
      G.up_t = G.now
    end
  end

  sfx_tick()

  -- 清掉已飘完的 (倒序删除: 顺序删会让后面的元素前移、漏检)
  local ps = G.pops
  for i = #ps, 1, -1 do
    if (G.now - ps[i].t) > POP_MS then table.remove(ps, i) end
  end

  save_state(false)

  -- 弹窗结果分发 (app.dlg.result 是"取走式": 读完自动清零, 每帧读不会误触发)
  local r = app.dlg.result()
  if r ~= nil then
    -- ★ 弹窗刚关: 记时刻, 并**要求先看到一次抬起**再认下一次按压。
    --   弹窗是 modal 页, 关掉那一帧手指往往还按在屏幕上(点弹窗那一下),
    --   坐标又正好落在木鱼热区里 ⇒ 不这样处理就会"点设置顺带敲一下木鱼"。
    G.dlg_close    = G.now
    G.t_down       = false
    G.need_release = true

    local st = G.pop
    G.pop = nil
    if st == "set" then
      if r == 0 then toggle("snd"); open_set()          -- 切换后重开: 项文字才会更新
      elseif r == 1 then toggle("vib"); open_set()
      elseif r == 2 then open_stat()
      elseif r == 3 then G.pop, G.pop_open_t = "clr", G.now; app.dlg.confirm("清空全部记录？")
      end
    elseif st == "clr" then
      if r >= 0 then clear_records() end                 -- 0=确定; -1=取消/返回 → 什么都不动
    end
    -- st == "stat": 只读, 点任意项/返回都只是关掉, 无副作用
  end

  -- 动画期间**每帧**重绘: 实测系统 100+ fps, 全画一帧 ~6ms(木槌已是几何绘制)。
  --   ★ 原来这里有个 30ms 节流, 那是给旧"逐字节 hex 解码位图"留的省 CPU 手段;
  --     现在位图走 app.bmpr(二进制)、木槌按角度现算, 30ms 节流反而把动画锁在 33fps
  --     —— 这才是"动画太卡"的直接原因之一(2026-11-23 linit 报障)。
  --   ★ 飘字改成多条后, 判据是"还有任何一条在飘", 而不是"距上一次敲击多久" ——
  --     否则连点时上一条还在飘, 却因为 hit_t 已过 MAL_ANIM 而停止重绘 ⇒ 画面卡住不动。
  local busy = (G.now - G.hit_t) < MAL_ANIM or #G.pops > 0

  -- 佛光呼吸: 每 HALO_STEP_MS 换一档才置脏 (约 8fps), 不做无意义的每帧全绘
  if halo_level() > 0 then
    local ph = math.floor(G.now / HALO_STEP_MS) % #HALO_BREATH + 1
    if ph ~= G.halo_ph then
      G.halo_ph = ph
      busy = true
    end
  end
  -- 祝福语条幅当天常驻, 但它是静态文字 —— 不需要为它单独续帧, 佛光呼吸/敲击已经在重绘。

  if busy then app.redraw() end
end

function action(a)
  if type(a) ~= "number" then return true end
  if a == A_BACK then
    -- ★ 主界面**不消费** BACK ⇒ 框架 lua_request_exit 弹系统「退出程序?」标准确认框
    --   (page_lua.c:1190-1197)。确认才退, 取消留在原处。应用侧不画任何东西。
    return false
  elseif a == A_OK then
    do_hit()
    return true
  end
  return true
end

function on_enter()
  G.now = app.millis() or 0
  G.session = 0
  G.pop = nil
  G.hit_t = -10000
  G.pops = {}                     -- 重新进应用: 清空残留飘字 (旧表交给 GC)
  G.t_down = false
  G.up_t = -10000
  G.last_tap = -1000
  G.sfx_try = nil
  G.dirty = false
  G.dlg_close = nil
  G.need_release = true           -- 进应用那一下是点图标: 必须先抬起才算下一次按压
  -- 祝福语条幅现在是"当天常驻"(linit 2026-11-23), 不能再在这里清掉 ——
  --   它由 halo_level() + G.bless_i 决定, 重进应用应当还在。
  G.halo_ph = 1
  app.exit_confirm(true)          -- 主界面 BACK 由框架弹系统「退出程序?」(默认即开, 显式声明意图)
  -- ★ 全屏应用不要状态栏。声明按页归属(svc_statusbar.c:54 sb_effective_page),
  --   弹窗期间 DIALOG 页沿用底下这页 ⇒ 退出确认弹出时也不会突然冒出一条状态栏。
  app.statusbar(false)
  G.body = hex2bin(BODY_HEX)          -- 木鱼主体是位图; 木槌改成几何绘制, 不再预解码
  load_state()
  -- 今天已经敲满目标(比如上次是在旧版本里敲满的, 或关机前还没存连日):
  -- 进应用时就补记一次连日并放出祝福语 —— 佛光当帧亮起, 不用再等一次敲击。
  if G.today_ok and G.today >= GOAL then mark_goal() end
  refresh_strings()
  ensure_sfx()
  app.redraw()
end

function on_exit()
  G.now = app.millis() or G.now
  save_state(true)
  if app.rec and app.rec.stop_play then pcall(app.rec.stop_play) end
  -- ★ 卸载 PSRAM 音效缓存 (linit 2026-11-23: "该用就用, 退出了会卸载")
  --   预载占 52KB PSRAM; 不退就是把 PSRAM 白白占着, 多开几个应用就堆不下了。
  if app.rec and app.rec.unload then pcall(app.rec.unload) end
  G.sfx_ok = false
  G.body = nil                                -- 释放 PSRAM 上的位图副本
  G.pops = {}                                 -- 飘字列表随应用一起丢掉
end
